import java.util.*;
public class Main {
  public static void main(String[] args) {
    Scanner s=new Scanner(System.in); int n=s.nextInt(); long h=s.nextLong(); long[] p=new long[n]; long hi=0; for(int i=0;i<n;i++){p[i]=s.nextLong();hi=Math.max(hi,p[i]);} long l=1,r=hi; while(l<r){long m=l+(r-l)/2,hrs=0; for(long v:p){hrs+=(v+m-1)/m; if(hrs>h)break;} if(hrs<=h)r=m; else l=m+1;} System.out.println(l);
  }
}

