import java.util.*;
public class Main {
  public static void main(String[] args) {
    Scanner s=new Scanner(System.in); int n=s.nextInt(),d=s.nextInt(); long[] w=new long[n]; long l=0,r=0; for(int i=0;i<n;i++){w[i]=s.nextLong();l=Math.max(l,w[i]);r+=w[i];} while(l<r){long m=l+(r-l)/2;int days=1;long load=0;for(long x:w){if(load+x>m){days++;load=0;}load+=x;}if(days<=d)r=m;else l=m+1;}System.out.println(l);
  }
}
